def magic_square_test(square):
    if not square or len(square) == 0:
        return False

    n = len(square)
    # Check if it's an n x n matrix
    if any(len(row) != n for row in square):
        return False

    # Calculate the magic sum (sum of first row)
    magic_sum = sum(square[0])

    # Check if all rows sum to magic_sum
    for row in square:
        if sum(row) != magic_sum:
            return False

    # Check if all columns sum to magic_sum
    for col in range(n):
        col_sum = sum(square[row][col] for row in range(n))
        if col_sum != magic_sum:
            return False

    # Check if all diagonals sum to magic_sum
    sum_diag1 = sum(square[i][i] for i in range(n))
    sum_diag2 = sum(square[i][n - 1 - i] for i in range(n))

    if sum_diag1 != magic_sum or sum_diag2 != magic_sum:
        return False

    # Check if all numbers from 1 to n^2 are present exactly once
    flat = [num for row in square for num in row]
    if sorted(flat) != list(range(1, n * n + 1)):
        return False

    return True
```
